static void set_xfrm_gro_udp_encap_rcv(__u16 encap_type, unsigned short family,
				       struct sock *sk)
{
#ifdef CONFIG_XFRM
	if (udp_test_bit(GRO_ENABLED, sk) && encap_type == UDP_ENCAP_ESPINUDP) {
		struct udp_sock *up = udp_sk(sk);
		udp_tunnel_gro_receive_t new_gro_receive = NULL;

		if (family == AF_INET)
			new_gro_receive = xfrm4_gro_udp_encap_rcv;
		else if (IS_ENABLED(CONFIG_IPV6) && family == AF_INET6)
			new_gro_receive = ipv6_stub->xfrm6_gro_udp_encap_rcv;

		if (!new_gro_receive)
			return;

		if (up->gro_receive == new_gro_receive)
			return;

		if (udp_test_bit(ENCAP_ENABLED, sk))
			udp_tunnel_update_gro_rcv(sk, false);

		WRITE_ONCE(up->gro_receive, new_gro_receive);

		if (udp_test_bit(ENCAP_ENABLED, sk))
			udp_tunnel_update_gro_rcv(sk, true);
	}
#endif
}

